119:    // Largest n for which `n CHOOSE k` is guaranteed to be representable as an int
120:    private final static int maxIntChooseN = 33;
121:    private final static int[] tempIntChooseArray = new int[maxIntChooseN/2];
122:    private final static int[] intChooseTable = new int[chooseAccess(maxIntChooseN + 1, 2)];
123:
124:    // Entry k is the largest n for which `n CHOOSE (k+2)` can be computed by
125:    // the fast algorithm without overflow occurring at any intermediate step.
126:    private final static int[] maxIntChooseSafeN = { 46341, 1626, 338, 140, 82, 58, 46,
127:						  39, 35, 33, 31, 30, 30, 29, 29 };
128:    // This index computation uses the 1-D array intChooseTable densely to hold a strangely
129:    // triangular 2-D array. It should be used only for 4 <= n <= maxIntChooseN and 2 <= k <= n/2.
130:    // The 1-D array holds elements for (n,k) = (4,2) (5,2) (6,2) (6,3) (7,2) (7,3) (8,2) (8,3) (8,4)
131:    // (9,2) (9,3) (9,4) (10,2) (10,3) (10,4) (10,5) (11,2) (11,3) (11,4) (11,5) and so on.
132:    // This represents (slightly over) one-half of Pascal's triangle with the outermost two
133:    // layers discarded.
134:    private static int chooseAccess(int n, int k) { return ((n-3)>>1)*((n-2)>>1) + (k-2); }
135:
136:    static {
