138:	    for (int k = 2; k <= n/2; k++) {
139:		// The table entries for row n-1 are already done, so they are available for computing row n.
140:		intChooseTable[chooseAccess(n, k)] = intOverflowingChoose(n-1, k-1) + intOverflowingChoose(n-1, k);
141:	    }
142:	}
143:    }
