353:    // This version handles signed shift distances and checks for arithmetic overflow.
354:    public static int intShift(int a, int b) {
355:	if (b < 0) {
356:	    if (b < -31) return a >> 31;
357:	    else return a >> (-b);
358:        } else if (b > 31) {
359:	    if (a == 0) return 0;
360:	    else throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
361:        }
362:	else {
363:	    int result = a << b;
364:	    if ((result >> b) == a) return result;
365:	    else throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
366:	}
367:    }
